"""The Principia Metaphysica theory adapter: ``THEORY`` for the test ground.

* switches: `simulations.core.variants.FORKS` (implemented) plus the lineage
  catalogue's declared-only forks and options (``implemented=False``).
* selections: read-only, from `variants.active_selection()`.
* pipeline: one stage, ``python -m metaphysica.build --out . --fast``.
* signals / anchors: the minimum, read from a run root's ``AutoGenerated/``.
* decisions: the site's ``DECISION_LOG.md`` (env ``METAPHYSICA_DECISION_LOG``,
  else the sibling ``PrincipiaMetaphysica/docs`` found by walking up).
* lineage: ``lineage/branches.yaml``.

Copyright (c) 2025-2026 Andrew Keith Watts. All rights reserved.
"""

from __future__ import annotations

import json
import os
import sys
from pathlib import Path
from typing import Any, Dict, List, Mapping, Optional, Sequence

from metaphysica.simulations.core import variants
from metaphysica.testground.configurations.model import ACTIVE, Configuration
from metaphysica.testground.constraints import (Constraint,
                                                constraints_from_options)
from metaphysica.testground.graph.lineage_graph import merge_declared
from metaphysica.testground.lineage.load import load_lineage
from metaphysica.testground.signals.model import (ARTIFACT, FULL,
                                                  Measurement, Signal,
                                                  SignalContext)
from metaphysica.testground.switches import model as sw
from metaphysica.testground.theory import ScoredRow, Stage, Theory

__all__ = ["LINEAGE_PATH", "ENV_DECISION_LOG", "THEORY", "PmSwitches",
           "PmSelections", "PmPipeline", "PmAnchors", "PmSignals",
           "PmDecisions", "pm_forks", "find_decision_log", "make_theory"]

LINEAGE_PATH = Path(__file__).resolve().parent / "lineage" / "branches.yaml"
ENV_DECISION_LOG = "METAPHYSICA_DECISION_LOG"
_REPORT = "validation_report.json"


def pm_forks(lineage_path: Path = LINEAGE_PATH) -> Dict[str, sw.Fork]:
    """Engine forks (implemented) plus the catalogue's declared-only ones."""
    engine = dict(variants.FORKS)
    lineage = load_lineage(lineage_path, engine)
    return merge_declared(engine, lineage)


class PmSwitches:
    """SwitchProvider: the engine's forks plus the declared-only ones."""

    def __init__(self, lineage_path: Path = LINEAGE_PATH) -> None:
        self._forks = pm_forks(lineage_path)

    def forks(self) -> Mapping[str, sw.Fork]:
        return self._forks

    def constraints(self) -> Sequence[Constraint]:
        return constraints_from_options(self._forks)


class PmSelections:
    """SelectionStore: read-only, from the engine's own resolution."""

    def active(self) -> Configuration:
        return Configuration.of("pm", variants.active_selection(),
                                lifecycle=ACTIVE, name="active")

    def named(self) -> Mapping[str, Configuration]:
        return {}

    def write_active(self, cfg: Configuration, decision_id: str,
                     note: str = "") -> None:
        raise RuntimeError(
            "the pm selection is read-only: the engine's adopted options "
            "live in simulations/core/variants.py (no active.yaml yet); "
            "change them there and record the decision in DECISION_LOG.md")


class PmPipeline:
    """Pipeline: one fast build into the run root."""

    def stages(self) -> Sequence[Stage]:
        return (Stage(id="build", kind="compute",
                      command=(sys.executable, "-m", "metaphysica.build",
                               "--out", ".", "--fast")),)


def _validations(root: Path) -> Optional[List[Mapping[str, Any]]]:
    try:
        doc = json.loads((Path(root) / "AutoGenerated" / _REPORT)
                         .read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return None
    rows = doc.get("validations") if isinstance(doc, dict) else None
    return [r for r in rows if isinstance(r, dict)] \
        if isinstance(rows, list) else None


class PmAnchors:
    """AnchorProvider: the validation report's rows."""

    def scored_rows(self, root: Path) -> Sequence[ScoredRow]:
        rows = _validations(root)
        if rows is None:
            raise FileNotFoundError("no readable %s under %s/AutoGenerated"
                                    % (_REPORT, root))
        return [ScoredRow(id=str(r.get("id") or r.get("name") or i),
                          verdict=str(r.get("verdict")),
                          sigma=r.get("sigma_deviation"))
                for i, r in enumerate(rows)]


def _count(verdict: str):
    def evaluate(ctx: SignalContext) -> Measurement:
        rows = _validations(ctx.root)
        sid = "data.n_" + verdict.lower()
        if rows is None:
            return Measurement.unmeasured(sid, "no readable " + _REPORT)
        n = sum(1 for r in rows if r.get("verdict") == verdict)
        return Measurement(sid, count=n)
    return evaluate


class PmSignals:
    """SignalProvider: the minimum, the data rows of the validation report."""

    def signals(self) -> Sequence[Signal]:
        return tuple(
            Signal("data.n_" + v.lower(), "data", ARTIFACT, FULL, _count(v),
                   "validation rows with verdict " + v)
            for v in ("FAIL", "TENSION"))


def find_decision_log(start: Optional[Path] = None) -> Optional[Path]:
    """Env override, else ``PrincipiaMetaphysica/docs/DECISION_LOG.md`` beside
    an ancestor of this package; None when neither exists."""
    env = os.environ.get(ENV_DECISION_LOG)
    if env:
        return Path(env) if Path(env).is_file() else None
    here = Path(start or __file__).resolve()
    for parent in here.parents:
        cand = parent / "PrincipiaMetaphysica" / "docs" / "DECISION_LOG.md"
        if cand.is_file():
            return cand
    return None


class PmDecisions:
    """DecisionLogProvider: the site's log, or None (the graph then carries a
    provenance warning)."""

    def decision_log_path(self) -> Optional[Path]:
        return find_decision_log()


def make_theory(lineage_path: Path = LINEAGE_PATH) -> Theory:
    return Theory(
        id="pm",
        title="Principia Metaphysica",
        env_prefix=variants._ENV_PREFIX,
        switches=PmSwitches(lineage_path),
        selections=PmSelections(),
        pipeline=PmPipeline(),
        signals=PmSignals(),
        anchors=PmAnchors(),
        decisions=PmDecisions(),
        lineage=lineage_path,
    )


THEORY = make_theory()
